(5437762, 782396, 94855, '<td valign="top">very nice use of light</td>', 'very nice use of light', '2009-04-15 01:10:06.000000', NULL, 1),
(5437785, 781542, 105585, '<td valign="top">Good shot! Even better w/o the monopole in the backdrop.</td>', 'Good shot! Even better w/o the monopole in the backdrop.', '2009-04-15 01:17:12.000000', NULL, 1),
(5437818, 782418, 83313, '<td valign="top">I think you missed meeting another member at this spot by an hour or two.</td>', 'I think you missed meeting another member at this spot by an hour or two.', '2009-04-15 01:25:17.000000', NULL, 1),
(5437822, 782446, 83313, '<td valign="top">Seems a bit soft somehow. I do like the perspective given by the long zoom you used for this.</td>', 'Seems a bit soft somehow. I do like the perspective given by the long zoom you used for this.', '2009-04-15 01:26:15.000000', NULL, 1),
