(5438246, 782334, 97475, '<td valign="top">Nice colours and lighting.</td>', 'Nice colours and lighting.', '2009-04-15 09:01:34.000000', NULL, 1),
(5438254, 781120, 97475, '<td valign="top">Nice perspective and composition.</td>', 'Nice perspective and composition.', '2009-04-15 09:03:57.000000', NULL, 1),
(5438259, 782126, 97475, '<td valign="top">I think the lighting is too unbalance. The dark is too dark and the white is too white.</td>', 'I think the lighting is too unbalance. The dark is too dark and the white is too white.', '2009-04-15 09:06:15.000000', NULL, 1),
(5438260, 781506, 89116, '<td valign="top">Very nice shot!  It seems to me that the highlights seem to be a bit blown and over-saturated, could just be me though.</td>', 'Very nice shot!  It seems to me that the highlights seem to be a bit blown and over-saturated, could just be me though.', '2009-04-15 09:06:59.000000', NULL, 1),
(5438263, 781700, 23484, '<td valign="top">You got a good angle on this.</td>', 'You got a good angle on this.', '2009-04-15 09:07:48.000000', NULL, 1),
(5438265, 781958, 97475, '<td valign="top">I notice some hot spots around her face and on the background wall.</td>', 'I notice some hot spots around her face and on the background wall.', '2009-04-15 09:08:02.000000', NULL, 1),
(5438266, 781745, 89116, '<td valign="top">My eyes are following the railroad tracks but I feel like I''m losing head room.  If you can I would re-compose with a little more room above the top of the tracks.  Very nice shot, but having those leading lines would make it much better.</td>', 'My eyes are following the railroad tracks but I feel like I''m losing head room.  If you can I would re-compose with a little more room above the top of the tracks.  Very nice shot, but having those leading lines would make it much better.', '2009-04-15 09:08:52.000000', NULL, 1),
