(5439212, 781536, 104198, '<td valign="top">I would have liked to seen this with a tighter crop, but find it so compelling it gets one of the few 10''s I''m giving out this challenge.</td>', 'I would have liked to seen this with a tighter crop, but find it so compelling it gets one of the few 10''s I''m giving out this challenge.', '2009-04-15 16:51:30.000000', NULL, 1),
(5439214, 782380, 105333, '<td valign="top">Beautiful colors</td>', 'Beautiful colors', '2009-04-15 16:52:39.000000', NULL, 1),
