(5439259, 781664, 105585, '<td valign="top">I would''ve liked to see more of (closer view) the "runaway''s" expression, but otherwise good composition.</td>', 'I would''ve liked to see more of (closer view) the "runaway''s" expression, but otherwise good composition.', '2009-04-15 17:29:28.000000', NULL, 1),
(5439266, 782228, 96823, '<td valign="top">Nice shot, IMO the gray box, the overpass and the blue door on the last building are a little distracting.JMO! Overall it''s a good shot.</td>', 'Nice shot, IMO the gray box, the overpass and the blue door on the last building are a little distracting.JMO! Overall it''s a good shot.', '2009-04-15 17:39:52.000000', NULL, 1),
(5439267, 782396, 96823, '<td valign="top">Nicely done!</td>', 'Nicely done!', '2009-04-15 17:40:39.000000', NULL, 1),
(5439270, 781721, 96823, '<td valign="top">It''s a nice shot, to me this is just a snap shot of a train sorry. JMO!</td>', 'It''s a nice shot, to me this is just a snap shot of a train sorry. JMO!', '2009-04-15 17:44:01.000000', NULL, 1),
(5439275, 781148, 96823, '<td valign="top">Nice shot but the use of a polarizer to remove the glare of the window would have made it better. JMO!</td>', 'Nice shot but the use of a polarizer to remove the glare of the window would have made it better. JMO!', '2009-04-15 17:47:46.000000', NULL, 1),
(5439280, 782131, 96823, '<td valign="top">IMO the train moving would have been better then using the zoom to make motion.</td>', 'IMO the train moving would have been better then using the zoom to make motion.', '2009-04-15 17:50:04.000000', NULL, 1),
(5439282, 781605, 96823, '<td valign="top">Nicely done!</td>', 'Nicely done!', '2009-04-15 17:50:52.000000', NULL, 1),
(5439288, 781709, 96823, '<td valign="top">Nicely done, but I think a lower angle would have been better to hide the background on leftside of the photo. JMO!</td>', 'Nicely done, but I think a lower angle would have been better to hide the background on leftside of the photo. JMO!', '2009-04-15 17:55:04.000000', NULL, 1),
(5439290, 782232, 96823, '<td valign="top">Nics shot, but it''s a little dark IMO.</td>', 'Nics shot, but it''s a little dark IMO.', '2009-04-15 17:56:19.000000', NULL, 1),
(5439318, 782021, 96823, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2009-04-15 18:39:51.000000', NULL, 1),
(5439321, 782351, 96823, '<td valign="top">To me it''s over processed. JMO!</td>', 'To me it''s over processed. JMO!', '2009-04-15 18:47:17.000000', NULL, 1),
(5439326, 781383, 96823, '<td valign="top">I know it''s a shot of a train at night, but the shot either needs more train or a slower shutter speed. JMO!</td>', 'I know it''s a shot of a train at night, but the shot either needs more train or a slower shutter speed. JMO!', '2009-04-15 18:56:17.000000', NULL, 1);
