(5440177, 782040, 98141, '<td valign="top">Great, clear shot with good color and great focus. I like that you included a bit from the car in front and a bit from the car behind, that''s what makes this photo well-composed imo.</td>', 'Great, clear shot with good color and great focus. I like that you included a bit from the car in front and a bit from the car behind, that''s what makes this photo well-composed imo.', '2009-04-16 10:07:05.000000', NULL, 1),
(5440179, 782420, 98141, '<td valign="top">Nice shot, the train does seem to be glowing a little bit, especially near the 9575 (perhaps the sun is right behind that corner or perhaps it''s an editing halo) but in combination with the dark sky it almost gives it a ghostly feel that I like.</td>', 'Nice shot, the train does seem to be glowing a little bit, especially near the 9575 (perhaps the sun is right behind that corner or perhaps it''s an editing halo) but in combination with the dark sky it almost gives it a ghostly feel that I like.', '2009-04-16 10:08:33.000000', NULL, 1),
(5440180, 781543, 98141, '<td valign="top">Not enough going on here. Dull colors, dull composition. Crop is too tight imho to give it an abandoned feel or to give it depth.</td>', 'Not enough going on here. Dull colors, dull composition. Crop is too tight imho to give it an abandoned feel or to give it depth.', '2009-04-16 10:09:25.000000', NULL, 1),
