(5441979, 782229, 99311, '<td valign="top">the exposure is bit low and that has brought down the contrast as well.. I guess might be due to the grey and dull atmosphere (cloud)</td>', 'the exposure is bit low and that has brought down the contrast as well.. I guess might be due to the grey and dull atmosphere (cloud)', '2009-04-17 14:16:54.000000', NULL, 1),
(5441982, 781389, 99311, '<td valign="top">nice photo .. without the title it would have been difficult for me to relate to this photo.</td>', 'nice photo .. without the title it would have been difficult for me to relate to this photo.', '2009-04-17 14:17:44.000000', NULL, 1),
