(5441988, 781680, 99311, '<td valign="top">good photograph ..sharp and vivid. If there was something else along with the railroads, it would have definitely raised more interest...</td>', 'good photograph ..sharp and vivid. If there was something else along with the railroads, it would have definitely raised more interest...', '2009-04-17 14:21:52.000000', NULL, 1),
(5441990, 782447, 83313, '<td valign="top">Nice use of the tilt and the start trails look cool like this.</td>', 'Nice use of the tilt and the start trails look cool like this.', '2009-04-17 14:22:16.000000', NULL, 1),
