(5441994, 782228, 83313, '<td valign="top">Nice perspective. Comes across a bit dark on my monitor. Maybe that''s intentional.</td>', 'Nice perspective. Comes across a bit dark on my monitor. Maybe that''s intentional.', '2009-04-17 14:25:22.000000', NULL, 1),
