INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5443135, 781810, 96823, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2009-04-18 17:12:55.000000', NULL, 1),
(5443136, 782272, 96823, '<td valign="top">Nice shot&gt;</td>', 'Nice shot>', '2009-04-18 17:13:14.000000', NULL, 1),
(5443138, 781850, 96823, '<td valign="top">Overall it''s a nice shot.</td>', 'Overall it''s a nice shot.', '2009-04-18 17:16:42.000000', NULL, 1),
(5443139, 781860, 105296, '<td valign="top">Love the lines and framing in this.</td>', 'Love the lines and framing in this.', '2009-04-18 17:20:54.000000', NULL, 1),
(5443140, 781515, 79079, '<td valign="top">My personal favorite entry in this challenge.  I wanted to do something very similar to this, but couldn''t find a suitable location.  I''m pretty happy with what I ended up with -- but I love this shot -- this is precisely what came to mind for me when I read about this challenge.<br/> <br/>My grandfather used to take me walking on the railroad tracks just down the road from their house when I was a very little boy.  I still have a collection of old spikes and plates we''d "clean up" from time to time.  The old rusty spikes and rails really bring back great memories.</td>', 'My personal favorite entry in this challenge.  I wanted to do something very similar to this, but couldn''t find a suitable location.  I''m pretty happy with what I ended up with -- but I love this shot -- this is precisely what came to mind for me when I read about this challenge. My grandfather used to take me walking on the railroad tracks just down the road from their house when I was a very little boy.  I still have a collection of old spikes and plates we''d "clean up" from time to time.  The old rusty spikes and rails really bring back great memories.', '2009-04-18 17:27:20.000000', NULL, 1),
(5443166, 781867, 96823, '<td valign="top">Nicely done!</td>', 'Nicely done!', '2009-04-18 18:02:32.000000', NULL, 1),
