(5444956, 782342, 73394, '<td valign="top"><strike></strike></td>', '', '2009-04-20 07:54:54.000000', NULL, 1),
(5445011, 782089, 96823, '<td valign="top">It''s an ok shot, it''s a little bright and I think that your focus should have been on one car or other to where it''s not so busy. JMO!</td>', 'It''s an ok shot, it''s a little bright and I think that your focus should have been on one car or other to where it''s not so busy. JMO!', '2009-04-20 09:35:01.000000', NULL, 1),
(5445014, 782265, 96823, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2009-04-20 09:36:16.000000', NULL, 1),
(5445018, 782065, 96823, '<td valign="top">Overall it''s a nice shot.</td>', 'Overall it''s a nice shot.', '2009-04-20 09:37:58.000000', NULL, 1),
(5445022, 781505, 96823, '<td valign="top">Nicely done!</td>', 'Nicely done!', '2009-04-20 09:38:34.000000', NULL, 1),
(5445033, 781745, 96823, '<td valign="top">To me it''s no more then a snap shot and croped low to hide the background. JMO!</td>', 'To me it''s no more then a snap shot and croped low to hide the background. JMO!', '2009-04-20 09:43:11.000000', NULL, 1),
(5445036, 781854, 96823, '<td valign="top">IMO I would have like to seen the tracks go all the way to the end of the tunnel. JMO!</td>', 'IMO I would have like to seen the tracks go all the way to the end of the tunnel. JMO!', '2009-04-20 09:47:09.000000', NULL, 1),
(5445043, 781389, 96823, '<td valign="top">I''m asumming thats a box car in the background, the pole on the right side of the photo is a little distracting. I thinking a higher angle to where you can see some of the tracks. JMO! Overall it''s a nice shot.</td>', 'I''m asumming thats a box car in the background, the pole on the right side of the photo is a little distracting. I thinking a higher angle to where you can see some of the tracks. JMO! Overall it''s a nice shot.', '2009-04-20 09:53:57.000000', NULL, 1),
(5445048, 782247, 96823, '<td valign="top">It''s a little bright, the colors a dull. IMO</td>', 'It''s a little bright, the colors a dull. IMO', '2009-04-20 09:57:35.000000', NULL, 1),
(5445056, 781579, 96823, '<td valign="top">Overall its a nice shot to bad you couldn''t have moved the trash can, I like fact that it looks like an old color photo.</td>', 'Overall its a nice shot to bad you couldn''t have moved the trash can, I like fact that it looks like an old color photo.', '2009-04-20 10:02:23.000000', NULL, 1),
(5445068, 782222, 96823, '<td valign="top">I like the grainy effect, but this is to grainy IMO.</td>', 'I like the grainy effect, but this is to grainy IMO.', '2009-04-20 10:05:57.000000', NULL, 1),
(5445074, 782433, 96823, '<td valign="top">Nice shot, but it looks to be a little over sharpened. JMO</td>', 'Nice shot, but it looks to be a little over sharpened. JMO', '2009-04-20 10:08:06.000000', NULL, 1),
(5445223, 781301, 83544, '<td valign="top">When it comes to trains and railroads I really don''t like macro...come on people there so much more to be seen from them</td>', 'When it comes to trains and railroads I really don''t like macro...come on people there so much more to be seen from them', '2009-04-20 12:03:06.000000', NULL, 1),
(5445224, 781678, 83544, '<td valign="top">the blurry thing is really distracting</td>', 'the blurry thing is really distracting', '2009-04-20 12:04:05.000000', NULL, 1),
(5445234, 781452, 48268, '<td valign="top">I would love to see this from a different angle.</td>', 'I would love to see this from a different angle.', '2009-04-20 12:10:26.000000', NULL, 1),
(5445290, 781536, 48268, '<td valign="top">Could use a little more contrast - or be shot at a different time of day.  All the greys are like blurring into eachother.</td>', 'Could use a little more contrast - or be shot at a different time of day.  All the greys are like blurring into eachother.', '2009-04-20 12:39:21.000000', NULL, 1),
(5445293, 782232, 48268, '<td valign="top">This is another one that should have been shot at a different time of day.  The train is almost obscured by the shadow of the hill.</td>', 'This is another one that should have been shot at a different time of day.  The train is almost obscured by the shadow of the hill.', '2009-04-20 12:40:46.000000', NULL, 1),
(5445328, 781068, 48268, '<td valign="top">That''s awful!  LOL!</td>', 'That''s awful!  LOL!', '2009-04-20 13:01:34.000000', NULL, 1),
(5445477, 782057, 83313, '<td valign="top">Nice deadpan title!</td>', 'Nice deadpan title!', '2009-04-20 14:23:49.000000', NULL, 1),
(5445478, 782365, 83313, '<td valign="top">Ouch. Good find.</td>', 'Ouch. Good find.', '2009-04-20 14:24:29.000000', NULL, 1),
(5445485, 782348, 83313, '<td valign="top">Not caring for the negative treatment. I reversed it and I do like the positive of this.</td>', 'Not caring for the negative treatment. I reversed it and I do like the positive of this.', '2009-04-20 14:26:28.000000', NULL, 1),
(5445488, 781723, 83313, '<td valign="top">I like it. My major nitpick,however, is how close to the right edge of the frame the engine is cropped. Cut off a little in fact. I suspect there may be something distracting off to that side.</td>', 'I like it. My major nitpick,however, is how close to the right edge of the frame the engine is cropped. Cut off a little in fact. I suspect there may be something distracting off to that side.', '2009-04-20 14:29:39.000000', NULL, 1),
(5445508, 781641, 104020, '<td valign="top">Sat racking my brains for a title......but i''ll keep you in suspension.</td>', 'Sat racking my brains for a title......but i''ll keep you in suspension.', '2009-04-20 14:48:27.000000', NULL, 1),
(5445516, 781974, 104020, '<td valign="top">Nice shot</td>', 'Nice shot', '2009-04-20 14:52:23.000000', NULL, 1),
(5445529, 782201, 15495, '<td valign="top">Nice colors... good timing</td>', 'Nice colors... good timing', '2009-04-20 15:01:39.000000', NULL, 1),
(5445530, 781679, 15495, '<td valign="top">I like it ...its different.</td>', 'I like it ...its different.', '2009-04-20 15:01:57.000000', NULL, 1),
(5445531, 781974, 15495, '<td valign="top">Nicely done.</td>', 'Nicely done.', '2009-04-20 15:02:16.000000', NULL, 1),
(5445537, 781127, 15495, '<td valign="top">Looks like a postcard</td>', 'Looks like a postcard', '2009-04-20 15:03:51.000000', NULL, 1),
(5445541, 781249, 100971, '<td valign="top">In my humble opinon, I would have liked to see more of the train.  I think it would have filled the void within the center of the photo.  Aside from that.  I like the way you captured multiple aspects of railroading (train, rails, clock, station, people) all at once.</td>', 'In my humble opinon, I would have liked to see more of the train.  I think it would have filled the void within the center of the photo.  Aside from that.  I like the way you captured multiple aspects of railroading (train, rails, clock, station, people) all at once.', '2009-04-20 15:07:27.000000', NULL, 1),
(5445543, 781888, 100971, '<td valign="top">Not sure of the name of the visual effect you are using... but, I am not a big fan of it.  I believe that streaks going down the track, rather than a sun-burst wold have created a better dynamic effect.</td>', 'Not sure of the name of the visual effect you are using... but, I am not a big fan of it.  I believe that streaks going down the track, rather than a sun-burst wold have created a better dynamic effect.', '2009-04-20 15:09:39.000000', NULL, 1),
(5445547, 782170, 100971, '<td valign="top">I think I understand what you were attempting to achieve.  Sadly, you missed it by a few feet.  Too bad you couldn''t lean out a little further or waited until the train made a right curve.</td>', 'I think I understand what you were attempting to achieve.  Sadly, you missed it by a few feet.  Too bad you couldn''t lean out a little further or waited until the train made a right curve.', '2009-04-20 15:13:15.000000', NULL, 1),
(5445549, 782365, 100971, '<td valign="top">Wasn''t sure what I was looking at the first time.  Too bad ther wasn''t more of the bike frame remaining.  In my humble opinion, a lower angle to the track to create a distance of travel would make a bit of an improvement.</td>', 'Wasn''t sure what I was looking at the first time.  Too bad ther wasn''t more of the bike frame remaining.  In my humble opinion, a lower angle to the track to create a distance of travel would make a bit of an improvement.', '2009-04-20 15:15:58.000000', NULL, 1),
